#include <stdio.h>
#include <stdlib.h>
#include <math.h>
#include "flint/flint.h"
#include "acb.h"
#include "acb_dft.h"

// Helper: compute a crude radius (max |Im|+|Re|) upper bound via arf_get_d from mid; FLINT acb carries radius.
// We only need a robust numeric ratio that tracks looseness; use acb_get_rad.

static double acb_abs_radius_sum(const acb_t z)
{
    double rad = acb_get_rad(z);
    return rad;
}

int main(void)
{
    const long n = 1L<<16; // 2^16
    const long prec = 128;
    const long prec2 = prec + 64;

    // Working: build rad2 plans for these precisions.
    // API: acb_dft_rad2_plan_t type and init functions.
    // Some FLINT versions name plan struct differently; we use the documented API from acb_dft.h.

    acb_dft_rad2_plan_t plan1;
    acb_dft_rad2_plan_t plan2;

    acb_dft_rad2_plan_init(&plan1, n, prec);
    acb_dft_rad2_plan_init(&plan2, n, prec2);

    // Create exact integer vector with zero input radius: set each entry as exact acb with rad 0.
    // Pattern: real=(i mod 19)-9, imag=(i mod 13)-6.
    acb_t *x = (acb_t*) flint_malloc(sizeof(acb_t)*n);
    for (long i=0;i<n;i++){
        acb_init(x[i]);
        fmpz_t a,b; fmpz_init(a); fmpz_init(b);
        long r = (i % 19L) - 9L;
        long im = (i % 13L) - 6L;
        fmpz_set_si(a, r);
        fmpz_set_si(b, im);
        acb_set_fmpz_fmpz(x[i], a, b);
        acb_set_rad(x[i], 0.0);
        fmpz_clear(a); fmpz_clear(b);
    }

    // Output arrays
    acb_t *y1 = (acb_t*) flint_malloc(sizeof(acb_t)*n);
    acb_t *y2 = (acb_t*) flint_malloc(sizeof(acb_t)*n);
    for (long i=0;i<n;i++){ acb_init(y1[i]); acb_init(y2[i]); }

    // Run inverse/forward? Use same direction for comparing radii.
    acb_dft_rad2(&plan1, y1, x, n);
    acb_dft_rad2(&plan2, y2, x, n);

    // Compute max output radius at precision prec and at reference precision prec2.
    double rlo = 0.0, rhi = 0.0;
    for (long i=0;i<n;i++){
        double rad1 = acb_get_rad(y1[i]);
        double rad2 = acb_get_rad(y2[i]);
        if (rad1 > rlo) rlo = rad1;
        if (rad2 > rhi) rhi = rad2;
    }

    double ratio = (rhi == 0.0) ? NAN : (rlo / rhi);

    printf("rad2_looseness_probe n=%ld prec=%ld rlo=%g rhi=%g ratio=%g\n", n, prec, rlo, rhi, ratio);

    for (long i=0;i<n;i++){ acb_clear(x[i]); acb_clear(y1[i]); acb_clear(y2[i]); }
    flint_free(x); flint_free(y1); flint_free(y2);
    acb_dft_rad2_plan_clear(&plan1);
    acb_dft_rad2_plan_clear(&plan2);
    return 0;
}
